    N = int(input_data[0])
    P = list(map(int, input_data[1:N + 1]))

    bit = [0] * (N + 1)

    def add(i, x):
        while i <= N:
            bit[i] += x
            i += i & -i

    for i in range(1, N + 1):
        add(i, 1)

    ans = [0] * N
    max_step = 1 << (N.bit_length() - 1)

    for i in range(N - 1, -1, -1):
        k = P[i]
        idx = 0
        step = max_step

        while step:
            nxt = idx + step
            if nxt <= N and bit[nxt] < k:
                idx = nxt
                k -= bit[nxt]
            step >>= 1

        pos = idx + 1
        ans[pos - 1] = i + 1
        add(pos, -1)

    print(*ans)

if __name__ == "__main__":
